import{_ as o,C as t,o as i,c as s,E as r,a2 as c}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/control-intent-20260917/retry-without-second-launch.figure.en.svg",w=JSON.parse('{"title":"No reply. Will retrying launch a second AI agent?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"No reply. Will retrying launch a second AI agent?","date":"2026-09-17","published_date":"2026-09-17","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"No reply. Will retrying launch a second AI agent?","summary":"The action may have happened even when its reply disappears. A real-file experiment separates replaying a recorded result from refusing an uncertain retry.","cover":"/assets/control-intent-20260917/retry-without-second-launch.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded original-code experiments; scope in article","pageClass":"control-intent-article"},"headers":[],"relativePath":"en/engineering/2026-09-17-retry-without-second-launch.md","filePath":"en/engineering/2026-09-17-retry-without-second-launch.md","lastUpdated":1789614884000}'),d={name:"en/engineering/2026-09-17-retry-without-second-launch.md"};function h(p,e,u,g,m,y){const a=t("ArticleCover"),n=t("ArticleTableScroll");return i(),s("div",null,[r(a,{image:"/assets/control-intent-20260917/retry-without-second-launch.cover-v1.png",kicker:"Open-source engineering · Experimental research",title:"No reply. Will retrying launch a second AI agent?",summary:"The action may have happened even when its reply disappears. A real-file experiment separates replaying a recorded result from refusing an uncertain retry.",version:"2026-09-17",languageHref:"/zh/engineering/2026-09-17-retry-without-second-launch",languageLabel:"中文"}),r(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="no-reply-will-retrying-launch-a-second-ai-agent" tabindex="-1">No reply. Will retrying launch a second AI agent? <a class="header-anchor" href="#no-reply-will-retrying-launch-a-second-ai-agent" aria-label="Permalink to &quot;No reply. Will retrying launch a second AI agent?&quot;">​</a></h1><p>You tap “Start agent” on your phone. A few seconds pass. Nothing answers.</p><p>Should you tap again? If the first request never arrived, that seems sensible. If the computer already began acting but its reply disappeared, another tap could create a second job.</p><p>Imagine two agents modifying separate copies of the files, leaving you to choose which work to keep. Duplicate work may also consume additional resources. These are possible consequences, not incidents observed in our experiment. They explain why the silent click matters: <strong>no reply is not evidence that nothing happened.</strong></p><h2 id="look-up-the-original-operation" tabindex="-1">Look up the original operation <a class="header-anchor" href="#look-up-the-original-operation" aria-label="Permalink to &quot;Look up the original operation&quot;">​</a></h2><p>The inspiration is <a href="https://github.com/stablyai/orca/pull/21106" target="_blank" rel="noreferrer">Orca #21106</a>, by brennanb2025. Orca connects remote devices, such as phones, with computers running AI agents. This change saves launch records to a file so a retry can recover an existing result.</p><p>We were interested because starting an agent may also create a workspace and a session. Repeated words can be ignored; two jobs may keep producing consequences.</p><p>The mechanism gives each launch an operation number. The first request and its retry use the same number, allowing the computer to look up the original record. In code, this is the operation ID. The check also considers the caller and task contents, so an old number cannot silently stand for a different request.</p><p>One distinction carries the design: <strong>“I accepted this operation” and “I completed this launch” need separate records.</strong></p><h2 id="what-does-the-record-contain-when-a-retry-arrives" tabindex="-1">What does the record contain when a retry arrives? <a class="header-anchor" href="#what-does-the-record-contain-when-a-retry-arrives" aria-label="Permalink to &quot;What does the record contain when a retry arrives?&quot;">​</a></h2><p>We ran the original code that stores these records and decides whether a launch may proceed, using real temporary files. We saved a synthetic successful result, discarded the initial response, then returned with the same operation number.</p><p>“Successful result” here means the result of launching, such as which workspace was returned. It does not mean the agent finished its subsequent assignment. No real agent ran in our probe.</p><table tabindex="0"><thead><tr><th>Controlled situation</th><th>What the retry returned</th></tr></thead><tbody><tr><td>Launch success saved, reply discarded</td><td>The same saved result</td></tr><tr><td>Operation accepted, final outcome missing</td><td>Unknown; another execution was refused</td></tr><tr><td>Same number, different task contents</td><td>Conflict: this is not the original request</td></tr></tbody></table><p>The first row shows why keeping records helps: a lost reply does not erase a saved result. The third shows why numbers cannot be reused indiscriminately. The second is harder to accept—if the operation was recorded, why can it not simply continue?</p><p><img src="'+l+'" alt="The same number returns: is the record complete?"></p><p><em>Figure 1. Source: author illustration from the real-file experiment. Completion here concerns the launch operation; successful outcomes were synthetic.</em></p><h2 id="what-happened-after-acceptance" tabindex="-1">What happened after acceptance? <a class="header-anchor" href="#what-happened-after-acceptance" aria-label="Permalink to &quot;What happened after acceptance?&quot;">​</a></h2><p>Suppose the computer records “I will execute this,” then loses contact before saving an outcome. That record alone allows at least three explanations: work never began, partly happened, or the launch finished without its final result being written.</p><p>An accepted operation therefore cannot be translated directly into either “not done” or “successful.” Executing again might duplicate work; declaring success might leave someone waiting for a job that does not exist.</p><p>The tested code preserves that uncertainty. Receiving the same number again does not issue another execution permission. We also reopened the store in the same process and could still recover saved results. That is not a test of complete recovery after power loss or a process crash.</p><p>At our read, the change had merged on September 17 UTC, but shipped clients did not yet supply the required outer operation ID. The source also explicitly leaves broader recovery outside this change. Our experiment explains how this record layer handles retries; it cannot establish protection for every tap in the mobile product.</p><h2 id="an-uncertain-answer-still-needs-a-next-step" tabindex="-1">An uncertain answer still needs a next step <a class="header-anchor" href="#an-uncertain-answer-still-needs-a-next-step" aria-label="Permalink to &quot;An uncertain answer still needs a next step&quot;">​</a></h2><p>Preventing a duplicate action matters. The person waiting still needs to decide whether to wait, inspect the work, or seek help.</p><p>Our experiment points toward evidence gathering: the original operation number, any still-running task and any resources already created could help reduce guesswork. Those are directions for future design and validation. We did not implement inspection or recovery.</p><p>Users can contribute a concrete timeline: what the interface said when the reply was missing, what they did next, and whether they later discovered work already running. That helps distinguish an action that never happened from a reply that never arrived.</p><p><strong>When a system can only say “unable to confirm,” what evidence should it provide so a person can confidently choose the next step?</strong></p><details><summary>Fixed revision, scope and complete observations</summary><h3 id="original-detailed-comparison" tabindex="-1">Original detailed comparison <a class="header-anchor" href="#original-detailed-comparison" aria-label="Permalink to &quot;Original detailed comparison&quot;">​</a></h3><p>Admission is the check that permits execution to begin. The eight-request result below concerns this layer only. The higher-level handler joins live work; it was not exercised, so seven refusals cannot be read as seven failed user retries.</p><table tabindex="0"><thead><tr><th>Controlled situation</th><th>Observed result</th></tr></thead><tbody><tr><td>Success was saved but the reply was discarded</td><td>Replayed the same saved result</td></tr><tr><td>Store reopened in the same process</td><td>Replayed the saved result</td></tr><tr><td>Same operation ID, changed task</td><td>Rejected as a conflict</td></tr><tr><td>Same paired device, rotated bearer token</td><td>Replayed the existing result</td></tr><tr><td>Operation claimed, final result missing</td><td>Refused another execution; outcome stayed unknown</td></tr><tr><td>Eight concurrent admissions for one operation</td><td>One execution admission; seven unknown refusals</td></tr></tbody></table><p>Revision: <code>d60ff2db02bf2b6c6ac4fd39c179c9854409d2a4</code>. We executed the complete original durableAgentSessionRecordStore plus admitAgentLaunchOperation, fingerprint and registry logic with real temporary files and proper-lockfile.</p><p>The 11 observations also cover caller partitioning between paired devices, replay of recorded failures, missing paired identity for remote callers, and an expired previously unseen operation ID. Bearer rotation retained the same paired-device identity.</p><p>The concurrent test stops at admission; the higher-level live-join handler was not exercised. Reopening occurred within one process. Saved launch outcomes were synthetic: no real workspace, model or mobile call was created.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-17-control-intent" target="_blank" rel="noreferrer">Results and reproduction scripts</a>. These observations do not establish a duplicate-launch defect or missing idempotency protection in CodeFlowMu.</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',28))])}const b=o(d,[["render",h]]);export{w as __pageData,b as default};
